import React, { useEffect, useRef, useState } from "react";

export interface OnboardingWizardProps {
  resume_token?: string;
  total_steps?: number;
  onStepChanged?: (payload: { from: number; to: number }) => void;
  onCompleted?: (payload: { profile: object }) => void;
  onAbandoned?: (payload: { last_step: number }) => void;
}

interface PersistedState {
  step: number;
  profile: { name: string; email: string };
  savedAt: number;
}

const STORAGE_KEY = "onboarding-wizard-state";
const TTL_MS = 24 * 60 * 60 * 1000;

const OnboardingWizard: React.FC<OnboardingWizardProps> = ({
  resume_token,
  total_steps = 3,
  onStepChanged,
  onCompleted,
  onAbandoned,
}) => {
  const clampedTotal = Math.min(10, Math.max(2, total_steps));

  const loadPersisted = (): PersistedState | null => {
    try {
      const key = resume_token ? `${STORAGE_KEY}:${resume_token}` : STORAGE_KEY;
      const raw =
        typeof window !== "undefined" ? window.localStorage.getItem(key) : null;
      if (!raw) return null;
      const parsed: PersistedState = JSON.parse(raw);
      if (Date.now() - parsed.savedAt > TTL_MS) return null;
      return parsed;
    } catch {
      return null;
    }
  };

  const persisted = loadPersisted();

  const [step, setStep] = useState<number>(persisted?.step ?? 1);
  const [profile, setProfile] = useState<{ name: string; email: string }>(
    persisted?.profile ?? { name: "", email: "" }
  );
  const [completed, setCompleted] = useState(false);
  const stepRef = useRef(step);
  const completedRef = useRef(completed);

  useEffect(() => {
    stepRef.current = step;
  }, [step]);

  useEffect(() => {
    completedRef.current = completed;
  }, [completed]);

  const persist = (s: number, p: { name: string; email: string }) => {
    try {
      const key = resume_token ? `${STORAGE_KEY}:${resume_token}` : STORAGE_KEY;
      const data: PersistedState = {
        step: s,
        profile: p,
        savedAt: Date.now(),
      };
      if (typeof window !== "undefined") {
        window.localStorage.setItem(key, JSON.stringify(data));
      }
    } catch {
      /* ignore */
    }
  };

  useEffect(() => {
    persist(step, profile);
  }, [step, profile]);

  useEffect(() => {
    const handleUnload = () => {
      if (!completedRef.current) {
        onAbandoned?.({ last_step: stepRef.current });
      }
    };
    if (typeof window !== "undefined") {
      window.addEventListener("beforeunload", handleUnload);
    }
    return () => {
      if (typeof window !== "undefined") {
        window.removeEventListener("beforeunload", handleUnload);
      }
      if (!completedRef.current) {
        onAbandoned?.({ last_step: stepRef.current });
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const goTo = (target: number) => {
    if (target < 1 || target > clampedTotal) return;
    const from = step;
    onStepChanged?.({ from, to: target });
    setStep(target);
  };

  const isProfileValid = profile.name.trim() !== "" && /\S+@\S+/.test(profile.email);

  const handleNext = () => {
    if (step === 2 && !isProfileValid) return;
    if (step < clampedTotal) {
      goTo(step + 1);
    }
  };

  const handleBack = () => {
    if (step > 1) {
      goTo(step - 1);
    }
  };

  const handleComplete = () => {
    setCompleted(true);
    completedRef.current = true;
    onCompleted?.({ profile });
    try {
      const key = resume_token ? `${STORAGE_KEY}:${resume_token}` : STORAGE_KEY;
      if (typeof window !== "undefined") {
        window.localStorage.removeItem(key);
      }
    } catch {
      /* ignore */
    }
  };

  const renderStep = () => {
    if (step === 1) {
      return (
        <div>
          <h2>Willkommen</h2>
          <p>Schön, dass du da bist. Lass uns starten.</p>
        </div>
      );
    }
    if (step === 2) {
      return (
        <div>
          <h2>Profil-Daten</h2>
          <label>
            Name:
            <input
              type="text"
              value={profile.name}
              onChange={(e) =>
                setProfile((p) => ({ ...p, name: e.target.value }))
              }
            />
          </label>
          <label>
            E-Mail:
            <input
              type="email"
              value={profile.email}
              onChange={(e) =>
                setProfile((p) => ({ ...p, email: e.target.value }))
              }
            />
          </label>
          {!isProfileValid && <p>Bitte fülle alle Felder korrekt aus.</p>}
        </div>
      );
    }
    if (step === clampedTotal) {
      return (
        <div>
          <h2>Bestätigung</h2>
          <p>Name: {profile.name}</p>
          <p>E-Mail: {profile.email}</p>
          {completed && <p>Onboarding abgeschlossen!</p>}
        </div>
      );
    }
    return (
      <div>
        <h2>Schritt {step}</h2>
      </div>
    );
  };

  return (
    <div className="onboarding-wizard">
      <div>
        Schritt {step} von {clampedTotal}
      </div>
      {renderStep()}
      <div>
        <button type="button" onClick={handleBack} disabled={step === 1}>
          Zurück
        </button>
        {step < clampedTotal ? (
          <button
            type="button"
            onClick={handleNext}
            disabled={step === 2 && !isProfileValid}
          >
            Weiter
          </button>
        ) : (
          <button type="button" onClick={handleComplete} disabled={completed}>
            Abschließen
          </button>
        )}
      </div>
    </div>
  );
};

export default OnboardingWizard;
